"""Publish completed GPU-only sparse research, with explicit cost/layout limits."""
from pathlib import Path
import collections,hashlib,html,json,sys
ROOT=Path(__file__).resolve().parents[1];M=ROOT/'module_14_lm_head_v4';R=M/'reports/sparse_methods_20261024_r1';B=R/'benchmark'
def read(p):return json.loads(p.read_text(encoding='utf-8'))
def esc(v):return html.escape(str(v),quote=True)
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
NAMES=dict(dense='完整词表dense',cluster='原投票聚类',lowrank='原低秩',hybrid='原融合',partial='部分通道预筛',affinity='全词表倒排桶',learned='学习式桶路由',lsh='多表哈希')
METHODS=[
dict(mode='partial',title='研究11：部分通道预筛',count=16,steps=['读取hidden与列RMS','选择d个通道','遍历全词表计算d维预览','按history执行penalty并稳定Top-T','并入特殊ID，完整896维BF16精算'],parameters='dynamic：d=16/32/64/128，T=1024/4096/16384；static：d=32/128，T=4096/16384。dynamic按|h_j|×RMS(W[:,j])选通道；static按列RMS选固定通道。',fit='RMS仅由canonical W构造，不训练LM或读取校准标签。预览用所选通道顺序的相邻FP32树；其近似算术与原896维精算分别记录。',formula='selector ≈ V×d + [dynamic时H]；exact = K×H。预览BF16逻辑读取2Vd，精算2KH。Top-T排序输入仍是V。',fpga='动态方案需要列方向访问；保留行式W用于精算时，完整列式副本使两份W达到519.31MiB，已超旧320MiB arena。静态d128可只存37.09MiB预览列，d32为9.27MiB。权重预算只是下界，仍要加共同缓冲、输出、guard和对齐。',detail='可以按1024词一块存储[tile,channel,token]：块内分数只需4KiB，选择的d列按连续小突发读取，避免把全V分数都放BRAM。但跨通道归约顺序、动态地址、Top-T稳定同分规则和双布局loader都要另开发/验证。没有因此取得HLS或200MHz资格。'),
dict(mode='affinity',title='研究12：全词表权重亲和倒排桶',count=18,steps=['归一化原训练hidden中心','按W与中心亲和度为每词分配P个桶','查询h与C个原型的分数','选R桶、合并完整ID列表','完整BF16候选精算'],parameters='C=128/256，P=1/2，R=4/8/16/32；另C128/256、P1、R=C两个全词表端点。所有桶完整保存，不使用旧L上限截断。',fit='中心只来自原训练资产；token归桶使用完整canonical W，按亲和分数稳定取top-P。没有用校准标签选桶或拟合，所有151936词至少进入一个桶。',formula='selector = C×H；exact = K×H；ID读取 = 4E，其中E为所选桶条目总数，可能因P>1而大于最终K。',fpga='中心与查询点积很小，完整倒排ID索引只需4PV字节加偏移；桶内ID已按全局ID递增，有利于候选行读取。完整支持集解决了旧列表约9.9万词的来源上限，但小R是否命中仍完全由实测决定。',detail='全读R=C必为完整词表，作为正确性端点，不算稀疏收益。P增加会放大ID流量与重复去重；位图OR需处理同字更新冲突，不能丢bit。GPU用padding gather，FPGA可按真实counts流式读，但不能把这种潜在优化记成已测加速。'),
dict(mode='learned',title='研究13：训练集监督的线性桶筛选器',count=18,steps=['复用研究12的完整桶','从train dense赢家和rawTop256构造桶目标','拟合并冻结BF16线性筛选器＋FP32bias','查询时选R桶并去重','完整BF16候选精算'],parameters='与研究12相同18点；ridge均方目标正则λ=0.01，未调参。目标=winner的均分桶标签＋0.25×按1/rank归一化的rawTop256桶标签。',fit='只用原1500训练题/23933预测拟合。输入按通道中心化/标准化；折叠系数为BF16[C,896]和FP32bias。原LM及embedding/W未训练或量化。受Learning to Screen思路启发，是本项目ridge桶原型，不是论文模型复现。',formula='selector = C×H，再加C次bias加法；exact = K×H；完整ID桶为4PV字节，score排序输入仅C。',fpga='小型线性投影和偏置较容易形成流水线；候选构建可复用完整桶路径。但质量与最终K若不理想，筛选器便宜也不能抵消精算行数；不能把监督训练本身当作质量保证。',detail='训练目标来自带history penalty的dense标签，但当前桶分数仅输入hidden，history仍只在候选精算处理。这是已知模型能力边界。后续若改MLP/训练目标/候选来源，需另立方法和新最终组，不能继续用旧打开测试组认证。'),
dict(mode='lsh',title='研究14：角度／内积变换多表哈希',count=16,steps=['固定BF16随机超平面','构建每表完整倒排索引','h投影得到hash码','读取相同桶或Hamming1邻桶','并集去重，完整BF16精算'],parameters='angular/mips × b=8/10 × active tables=4/8 × Hamming radius=0/1；seed=20261024。当前GPU原型统一算8表投影，即使只探测4表，乘法项仍按8bH统计。',fit='angular直接按随机投影符号建桶；mips令M=max||w||，使用[w/M,sqrt(1−||w||²/M²)]和[h,0]的球面变换；查询正比例归一化不改变符号。完整W建索引，不使用训练/校准赢家标签。并非ALSH2014完整复现或有已验证的次线性速度保证。',formula='当前selector = 8×b×H；radius1读取桶数L×(b+1)，radius0为L。exact = K×H；ID读取4E；存8表ID为32V字节，另偏移和8b×H BF16投影。',fpga='投影乘法很少，随机offset查询与连续桶列表可分开流水；然而桶长偏斜、邻桶探测放大、去重与最终K可能主导。构建观察最大桶约5.9万–6.5万词，必须按真实长度处理，不能靠平均V/2^b估算缓冲。',detail='当前GPU variable gather会按本次最大桶长构造padding索引；FPGA可改为按counts逐桶流式，但需要另实现。MIPS球面增强受最大权重范数和投影偏斜影响，不能预设它一定优于角度哈希。原型没有用隐含dense fallback抬高召回。')]
def gate(p,t):
    q=p['quality']['decode'];return q['recall']>=t and all(v['recall']>=t for v in q['by_category'].values())
def endpoint(p):return p['mode'] in ['affinity','learned'] and p['parameters']['R']==p['parameters']['C']
def main():
    result=read(B/'RESULT.json');review=read(B/'INDEPENDENT_REVIEW.json');analysis=read(R/'ANALYSIS.json');profile=read(R/'STAGE_PROFILE.json')
    assert review['result_sha256']==analysis['result_sha256']==sha(B/'RESULT.json')
    assert len(result['configurations'])==len(analysis['rows'])==557
    assert read(R/'SELECTOR_REVIEW.json')['state']=='PASS_INDEPENDENT_NUMPY544_NEW_CALIBRATION_SELECTOR_CHECKS_AND_INDEX_SUPPORT'
    rows=result['configurations'];cost={p['id']:p for p in analysis['rows']};stages={p['id']:p for p in profile['records']};dense=next(p for p in rows if p['mode']=='dense');new=[p for p in rows if p['mode'] in ['partial','affinity','learned','lsh']];assert len(new)==68
    keypoints=[];findings=[]
    for mode in NAMES:
        group=[p for p in rows if p['mode']==mode and not endpoint(p)]
        if not group:continue
        passing=[p for p in group if gate(p,.99)]
        best=max(passing,key=lambda p:p['equivalent_m14_per_s']) if passing else max(group,key=lambda p:p['quality']['decode']['recall'])
        q=best['quality']['decode'];keypoints.append(best)
        findings.append(dict(mode=mode,configs=len([p for p in rows if p['mode']==mode]),nonendpoint_cal99=len(passing),nonendpoint_cal999=sum(gate(p,.999) for p in group),shown=best['id'],reason='各类校准≥99%中GPU最快，仅描述性观察' if passing else '未找到各类校准≥99%的稀疏点；展示最高整体召回点',recall=q['recall'],rate=best['equivalent_m14_per_s']))
    methods_html=[]
    for m in METHODS:
        group=[p for p in new if p['mode']==m['mode']];f=next(x for x in findings if x['mode']==m['mode']);best=next(x for x in rows if x['id']==f['shown']);q=best['quality']['decode'];c=cost[best['id']]
        flow=''.join(f'<span>{esc(x)}</span>' for x in m['steps'])
        methods_html.append(f'''<section class="card" id="{m['mode']}"><div class="kicker">{m['count']} CONFIGURATIONS · 校准与GPU已完成</div><h2>{esc(m['title'])}</h2><div class="flow">{flow}</div><dl><dt>参数</dt><dd>{esc(m['parameters'])}</dd><dt>来源与拟合</dt><dd>{esc(m['fit'])}</dd><dt>乘法与访存模型</dt><dd><code>{esc(m['formula'])}</code></dd><dt>本轮结果</dt><dd>非全词表端点中，各类校准≥99%有{f['nonendpoint_cal99']}个，≥99.9%有{f['nonendpoint_cal999']}个。{esc(f['reason'])}：<b>{esc(best['id'])}</b>，整体召回{q['recall']*100:.5f}%，漏{q['misses']}/{q['steps']}，GPU {best['equivalent_m14_per_s']:.2f}次/s；最低类别{min(x['recall'] for x in q['by_category'].values())*100:.5f}%。</dd><dt>该点逻辑预算</dt><dd>{c['total_multiplication_terms']/1e6:.2f}M乘法项；主逻辑读取{c['logical_main_read_bytes']/2**20:.2f}MiB；权重＋索引最低预算{c['stored_weight_and_index_lower_bound_bytes']/2**20:.2f}MiB（未含共同缓冲）。</dd><dt>FPGA适配</dt><dd>{esc(m['fpga'])}</dd><dt>实现约束</dt><dd>{esc(m['detail'])}</dd></dl></section>''')
    headers=['配置','校准召回/漏选','最低类别','K均值 / P95','GPU 次/s','对dense','selector/精算 ms','乘法项 M','主逻辑读取 MiB','权重＋索引 MiB']
    def tr(p):
        q=p['quality']['decode'];c=cost[p['id']];stage=stages.get(p['id']);time=f"{stage['selector_mean_ms']:.3f} / {stage['exact_policy_return_mean_ms']:.3f}" if stage else '未分阶段计时'
        return '<tr>'+''.join(f'<{tag}>{value}</{tag}>' for tag,value in [('th',esc(p['id'])+('（全桶端点）' if endpoint(p) else '')),('td',f"{q['recall']*100:.5f}%<br>{q['misses']}/{q['steps']}"),('td',f"{min(x['recall'] for x in q['by_category'].values())*100:.5f}%"),('td',f"{p['candidate_decode']['mean']:.2f} / {p['candidate_decode']['p95']}"),('td',f"{p['equivalent_m14_per_s']:.2f}"),('td',f"{p['equivalent_m14_per_s']/dense['equivalent_m14_per_s']:.3f}×"),('td',time),('td',f"{c['total_multiplication_terms']/1e6:.2f}"),('td',f"{c['logical_main_read_bytes']/2**20:.2f}"),('td',f"{c['stored_weight_and_index_lower_bound_bytes']/2**20:.2f}")])+'</tr>'
    table='<thead><tr>'+''.join('<th>'+h+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join(tr(p) for p in keypoints)+'</tbody>'
    focus_ids=['cluster_C128_R4_L16384','cluster_C256_R4_L16384','hybrid_C128_R4_L16384_r128_T16384','partial_dynamic_d64_T4096','partial_dynamic_d128_T1024','partial_dynamic_d128_T4096']
    focused=[next(p for p in rows if p['id']==key) for key in focus_ids]
    focus_table='<thead><tr>'+''.join('<th>'+h+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join(tr(p) for p in focused)+'</tbody>'
    alltable='<thead><tr>'+''.join('<th>'+h+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join(tr(p) for p in sorted(new,key=lambda p:-p['equivalent_m14_per_s']))+'</tbody>'
    best_new=max([p for p in new if not endpoint(p) and gate(p,.99)],key=lambda p:p['equivalent_m14_per_s'],default=None)
    best999=max([p for p in new if not endpoint(p) and gate(p,.999)],key=lambda p:p['equivalent_m14_per_s'],default=None)
    def outcome(p):
        if not p:return '本轮未找到。'
        q=p['quality']['decode'];return f"{p['id']}：{p['equivalent_m14_per_s']:.2f}次/s，整体召回{q['recall']*100:.5f}%，最低类别{min(c['recall'] for c in q['by_category'].values())*100:.5f}%，K均值{p['candidate_decode']['mean']:.2f}。"
    comments=[['按各类校准≥99%观察',outcome(best_new)],['按各类校准≥99.9%观察',outcome(best999)],['当前可作的研发决定','继续评审动态部分通道的双布局、Top-T和独立质量验证；保留原C128投票聚类及dense作控制。没有新最终组认证，本报告不指定上板发布参数。'],['不应直接硬件化的理由','全支持桶/哈希解决的是候选来源或查询成本，若当前少桶/少探测质量不足，或者K大到抵消筛选收益，应先改软件方法。全桶端点100%只验证完整性。'],['后续硬件流程','待用户选定研究方向后，再冻结新数值/地址/身份，准备独立质量组，进行Csim/HLS/RTL/200MHz与匹配软件；最终在新的独占安排下上板。本轮这些项目均NOT_RUN。']]
    narrative=''.join(f'<tr><th>{esc(k)}</th><td>{esc(v)}</td></tr>' for k,v in comments)
    source_links=''.join(f'<a href="../../{(p).relative_to(ROOT).as_posix()}">{esc(label)}</a>' for p,label in [(R/'PLAN.json','冻结68点方案'),(R/'PARAMETERS.json','模型/索引及训练身份'),(R/'CALIBRATION.json','68点校准'),(B/'RESULT.json','557点同轮GPU结果'),(B/'INDEPENDENT_REVIEW.json','独立数组与计时复核'),(R/'ANALYSIS.json','557点完整计算模型'),(R/'STAGE_PROFILE.json','72点分阶段计时'),(R/'resume_lsh_r2/ENTRY_LOCK.json','哈希索引类型失败与续办')])
    page=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>lm_head v4 · 更多稀疏方案GPU研究与FPGA适配分析</title><style>
    :root{{--ink:#20352f;--muted:#5d706a;--line:#d8e3dc;--bg:#f3f5ef;--green:#176955}}*{{box-sizing:border-box}}body{{margin:0;background:var(--bg);color:var(--ink);font:15px/1.8 "Segoe UI","Microsoft YaHei",sans-serif}}main{{max-width:1280px;margin:auto;padding:28px}}a{{color:var(--green)}}h1{{font-size:32px;line-height:1.35}}h2{{font-size:23px;margin-top:0}}h3{{font-size:18px}}.card{{background:#fffefa;border:1px solid var(--line);border-radius:14px;padding:24px;margin:22px 0}}.notice{{border-left:4px solid #92692c;background:#fff1d8;padding:13px 18px}}.kicker{{font-size:12px;letter-spacing:1.5px;color:var(--green);font-weight:700}}.flow{{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0}}.flow span{{background:#eaf2eb;border:1px solid #c0d1c2;padding:9px 12px;border-radius:8px;flex:1;min-width:150px}}.flow span+span:before{{content:'→ ';color:var(--green)}}dl{{display:grid;grid-template-columns:150px minmax(0,1fr);margin:0}}dt,dd{{border-top:1px solid var(--line);padding:12px;margin:0}}dt{{font-weight:700}}.scroll{{overflow:auto;max-height:650px}}table{{border-collapse:collapse;width:100%;font-size:13px}}th,td{{border:1px solid var(--line);padding:10px;text-align:left;vertical-align:top;overflow-wrap:anywhere}}th{{background:#eef3ee}}.scroll table{{min-width:1050px}}.scroll thead th{{position:sticky;top:0;background:#e7efe7}}code{{background:#eef1ed;padding:3px 5px;overflow-wrap:anywhere}}.links{{display:flex;flex-wrap:wrap;gap:13px}}.muted{{color:var(--muted);font-size:13px}}.anchors{{display:flex;gap:14px;flex-wrap:wrap}}@media(max-width:700px){{main{{padding:15px}}.card{{padding:16px}}dl{{grid-template-columns:1fr}}dt{{padding-bottom:0}}dd{{border-top:0}}h1{{font-size:26px}}}}
    </style></head><body><main><nav class="anchors"><a href="V4Validation.html#gpu-summary">← GPU汇总图</a><a href="#partial">部分通道</a><a href="#affinity">全词表桶</a><a href="#learned">学习路由</a><a href="#lsh">哈希</a><a href="#costs">计算量与FPGA</a></nav><header><p class="kicker">GPU-ONLY RESEARCH · 68 NEW / 557 SAME-RUN CONFIGURATIONS</p><h1>更多稀疏方案：先用GPU比较，再决定硬件方向</h1><p>完成时间：{esc(result['completed'])}，Asia/Shanghai。新增4类68配置；557点同轮66,840次完整M14计时＋660次dense哨兵，2,228组完整候选/raw位/输出核对，加8个其他校准步共544组独立CPU候选/K/命中复核；另72点共2,880次分阶段计时。</p><p class="notice">质量是原320校准题/4,775 decode的固定dense轨迹赢家覆盖，不是新的独立最终测试、闭环生成或任务正确率。速度是4固定校准输入的完整GPU M14输出率，不是整网decode、TTFT或FPGA性能。本轮未连接/探测/操作FPGA，未运行EDA。</p></header><section class="card"><h2>同轮结果与观察门槛</h2><p>只展示各家族一个有解释意义的点：若存在各类校准≥99%的非全桶点，显示其中GPU最快者；否则显示最高整体召回的非全桶点。所有68点均在后文和汇总图保留。门槛仅供研究比较，未改原实验结论或发布参数。</p><div class="scroll"><table>{table}</table></div><table>{narrative}</table></section><section class="card" id="tradeoffs"><h2>重点比较：GPU最快不等于FPGA成本最低</h2><p>下面把原C128/C256聚类、冻结融合和三个动态通道点并列。候选K与逻辑预算来自4,775个校准decode步；GPU速率来自4固定输入120次完整调用。分阶段是另一次带同步屏障的40次统计，不用于替代完整调用速率。</p><div class="scroll"><table>{focus_table}</table></div><p>动态64通道＋Top4096相比原C128聚类，乘法项约13.41M对17.05M、主逻辑读取25.57MiB对32.64MiB，但GPU较慢。动态128通道＋Top1024约20.38M乘法项、38.87MiB主逻辑读取，却是本轮新方案中各类校准≥99%与≥99.9%条件下GPU最快的点。具体数值及独立质量边界见表格；不能按其中一个指标直接宣布硬件胜者。</p></section>{''.join(methods_html)}
    <section class="card" id="costs"><h2>计算量与FPGA适配：怎样理解表中的预算</h2><p>H=896，V=151936，K为每步真实去重候选数，E为实际所读ID条目数（包含重复）。dense每步V×H=136,134,656个乘法项，BF16权重259.65625MiB。乘法项是算法产品数，不等于DSP数量或时钟周期；加法树、policy、排序和位图操作另计。</p><table><tr><th>原方案</th><th>乘法项</th><th>主要逻辑读取</th></tr><tr><td>仅聚类</td><td>CH＋KH</td><td>2CH＋4E＋2KH</td></tr><tr><td>仅低秩</td><td>r(H＋V)＋KH</td><td>2r(H＋V)＋2KH</td></tr><tr><td>原融合</td><td>CH＋r(H＋V)＋KH</td><td>2CH＋2r(H＋V)＋4E＋2KH</td></tr></table><h3>三个不能混用的量</h3><p>① 表中的读取量是假定指定布局下的逻辑字节，不含burst浪费、cache、history、分数/排序缓冲和AXI控制，未测实际AXI。② 存储预算是完整W加索引/预览副本的下界；低于320MiB不代表布局已通过，高于则已经需要新arena。③ 分阶段测量加入了同步屏障，是单独instrumented run；其阶段和不能替代主图中120次完整调用的实测速率。</p><h3>片上存储和流水线的具体约束</h3><ul><li>全词表候选位图18,992B，理想纯容量约9个BRAM18K；同字OR并发需要转发/合并，不能丢更新。实际资源还由端口、bank和综合决定。</li><li>全V FP32预览分数607,744B，若全部放片上，理想纯容量约264个BRAM18K；按1024词分块只需4KiB局部分数，但仍要完成全局Top-T。</li><li>只存候选ID与FP32分数需约8T字节：T1024为8KiB，T4096为32KiB，T16384为128KiB，尚未计入排序工作区。</li><li>静态通道可打包固定列；动态通道需要支持任意选列，采用分块列式副本可节省每步读取但增加约259.66MiB常驻权重。原行式精算权重仍需保留。</li><li>候选全局排序后，896维精算可按一行一行读取；桶/哈希的列表和offset流量、重复去重开销必须另计。GPU padding gather成本不能直接等同于FPGA的流式counts循环。</li><li>新预览树、动态地址、bias、Top-T、descriptor/版本身份、PS加载布局必须重新冻结。原v3.1/v4组件可作为父版本参考，不能继承新系统200MHz或实板资格。</li></ul><p><code>T≥max(主逻辑字节/B有效带宽，乘法项/(P并行乘法槽×f时钟))</code> 只是在指定布局和理想流水线下的乐观下界；B、P未实测，排序/调度等亦未计入，因此本报告不给出“FPGA预计快几倍”的数值。</p></section>
    <section class="card" id="all-results"><h2>全部68个新点：包含失败点与全桶端点</h2><p class="muted">完整557点及参数搜索见<a href="V4Validation.html#gpu-summary">GPU汇总图</a>；全部557点的计算模型可下载ANALYSIS.json。分阶段仅对新增68点和4个原控制测量。</p><div class="scroll"><table>{alltable}</table></div></section><section class="card"><h2>来源、划分、数值与复现</h2><p>模型与canonical BF16 W均不变。原train1500题/23933预测用于监督筛选器和原中心来源；原calibration320题/5095预测（4775decode）只用于本轮探索。两组按问题哈希互斥；数据采集先前已冻结。没有重新采集或使用任何已打开的最终1000题组调参。</p><p>GPU：RTX5060 Laptop / PyTorch2.13.0+cu130，权重和参数常驻；所有557点使用本轮同样的Eager固定FP32算术、每类3预热＋30测量，按轮随机交错并插入dense哨兵。旧结果保留为历史，新总览不拼接旧绝对速度。核心输出的候选ID/raw bits/token/score/CRC已与CPU参考比对。全桶端点证明完整性，不说明小R质量。</p><p>工程修复记录：首轮校准在52点后因NumPy无符号/有符号混合导致哈希索引float64而停止；失败保留。独立r2续办仅显式转uint32，补完16点，前52点数组SHA不变。算法/参数/原冻结PLAN未改。</p><p>研究参考：<a href="https://research.google/pubs/learning-to-screen-for-fast-softmax-inference-on-large-vocabulary-neural-networks/">Learning to Screen（ICLR2019）</a>、<a href="https://proceedings.mlr.press/v37/neyshabur15.html">On Symmetric and Asymmetric LSHs for Inner Product Search（ICML2015）</a>。本项目实现和论文模型/评测设置不同。</p><div class="links">{source_links}</div></section><footer class="muted">离线静态报告；无网络请求或实验执行。数值正确性、探索性校准质量、GPU性能与未来硬件资格分别记录。</footer></main></body></html>'''
    (ROOT/'doc/design/V4SparseMethods.html').write_text(page,encoding='utf-8')
    summary=dict(state='COMPLETE_GPU_SPARSE_METHOD_STUDY_NO_HARDWARE',configurations=68,combined_configurations=557,benchmark_sha256=sha(B/'RESULT.json'),review_sha256=sha(B/'INDEPENDENT_REVIEW.json'),analysis_sha256=sha(R/'ANALYSIS.json'),profile_sha256=sha(R/'STAGE_PROFILE.json'),selector_review_sha256=sha(R/'SELECTOR_REVIEW.json'),findings=findings,best_new_cal99=best_new['id'] if best_new else None,best_new_cal999=best999['id'] if best999 else None,hardware='NOT_RUN',new_final_quality='NOT_RUN',no_release_or_parameter_lock=True)
    (R/'RESULT.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    md=['# 更多稀疏方案GPU研究','',f"68个新点＋489旧点同轮完成；完整计时66840次，额外dense哨兵660次，完整数值证明2228组，分阶段2880次。完成{result['completed']}。",'',*['- '+k+'：'+v for k,v in comments],'','研究报告：doc/design/V4SparseMethods.html。GPU主图：doc/design/V4Validation.html#gpu-summary。', '', '无板卡/EDA/新最终质量/发布资格；原实验10质量失败保持。']
    (R/'RESULT.md').write_text('\n'.join(md)+'\n',encoding='utf-8')
    sys.path.insert(0,str(ROOT/'tools'));import render_v4_validation;render_v4_validation.render()
    print(json.dumps(summary,ensure_ascii=False,indent=2))
